DefConstantSymbol[Mbh];
SetCMetricSystem["Schwarzschild",
 Function[{t,r,theta,varphi}, DiagonalMatrix[
  {-(1-2Mbh/r), 1/(1-2Mbh/r), r^2, r^2 Sin[theta]^2}]],
 Assumptions -> Function[{t,r,theta,varphi},
  theoryAssumptions && Mbh > 0 && r > 2Mbh && 0 < theta < Pi]];

DefScalarFunction[scale];
SetCMetricSystem["FLRW",
 Function[{t,x,y,z}, DiagonalMatrix[{-1,scale[t]^2,scale[t]^2,scale[t]^2}]],
 Assumptions -> Function[{t,x,y,z}, theoryAssumptions && scale[t] > 0]];

